package typingtrainer;  
import com.sun.tools.javac.util.List;

import java.io.FileNotFoundException;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import java.util.*; 
import java.io.File;

public class App {     
    
    
    public int scoring(String input, String target){  
        input = input.strip(); 
        target = target.strip(); 
        
        int dist = levenshteinDistance(input, input.length(), target, target.length()); 
        return target.length() - dist;
    } 
    
    public String getRandomScentence(File afile) throws FileNotFoundException {  
        String scentence = "";  
        Random rand = new Random(); 
        int n = 0; 
        for (Scanner scanner = new Scanner(afile); scanner.hasNext(); ){ 
            ++n;  
            String line = scanner.nextLine();
            if (rand.nextInt(n) == 0) {
                scentence = line;
            }
        } 
        return scentence;

    }
    
    public int levenshteinDistance(String s1, int len1, String s2, int len2) { 

        if (len2 == 0){  
            return len1;      
        } 
        
        if (len1 == 0){  
            return len2;      
        } 
        
        if (s1.charAt(len1 - 1) == s2.charAt(len2 - 1)) {
            return levenshteinDistance(s1, len1 - 1, s2, len2 - 1); 
        } 
        
        int insertionDist = levenshteinDistance(s1, len1, s2, len2 - 1);
        int deletionDist = levenshteinDistance(s1, len1 - 1, s2, len2);
        int substitutionDist = levenshteinDistance(s1, len1 - 1, s2, len2 - 1);
        return 1 + Math.min(Math.min(insertionDist, deletionDist), substitutionDist);
    }   
    
    public String getUserInput(String target) {
        // Placeholder for user input logic
        // In a real application, this would capture input from the user
        return target; // For testing purposes, we return the target itself
    }
    
    public int[] gameloop(int scentenceCount){ 
        int score = 0; 
        int total = 0; 
        while (scentenceCount > 0) {  
            String target = getRandomSentence(); 
            String input = getUserInput(target); 
            score += scoring(input, target); 
            total += target.length(); 
            scentenceCount--; 

        }
        return new int[]{score, total};
    }
    
    public void startGame(int scentenceCount){  
        double startTime = System.currentTimeMillis();
        int[] results = gameloop(scentenceCount); 
        double endTime = System.currentTimeMillis(); 
        double elapsedTime = (endTime - startTime) / 1000.0; 
        int score = results[0]; 
        int total = results[1]; 
        System.out.println("Your score: " + score + "/" + total); 
        System.out.println("Elapsed time: " + elapsedTime + " seconds"); 
    }
    
    

    
    
    public String getGreeting() {
        return "Hello World!";
    }

    public static void main(String[] args) {
        System.out.println(new App().getGreeting());
    }
}
